import java.util.*;
public class Main {
    static class Route{ String method; String path; Route(String m,String p){method=m;path=p;} }
    public static void main(String[] a){
        List<Route> routes=Arrays.asList(new Route("GET","/users"),new Route("POST","/users"));
        String[][] reqs={{"POST","/users"},{"GET","/users"},{"DELETE","/users"},{"PUT","/users"}};
        for(String[] r:reqs){
            boolean pathMatch=false, methodMatch=false;
            for(Route rt:routes){
                if(rt.path.equals(r[1])){ pathMatch=true; if(rt.method.equals(r[0])) methodMatch=true; }
            }
            String status = methodMatch?"200 OK" : (pathMatch?"405 Method Not Allowed":"404 Not Found");
            System.out.println(r[0]+" "+r[1]+" -> "+status);
        }
    }
}
